WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pc_m_complex'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '复杂排列组合应用', 'kp-pc-m-complex', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "复杂排列组合应用"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "隔板、插空、捆绑大杂烩。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、解题原则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "永远遵循：先排要求最苛刻的特殊元素，再捆绑相邻元素，最后插空不相邻元素。"}]}]}$$ AS jsonb), NULL, '复杂排列组合应用的核心考点与实战推导。', category_node.id, CAST('["数量关系", "排列组合", "复杂排列组合应用"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pc_m_complex", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
